create function pg_temp.directory_check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.directory_error(stmt text,code text,label text)returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate=code then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: expected % for %',code,label;end$$;
create function pg_temp.directory_read(q jsonb default '{}')returns jsonb language sql as $$select public.read_directory('d1000000-0000-4000-8000-000000000001',(jsonb_build_object('tenantId','d1000000-0000-4000-8000-000000000001')||q)::text)$$;
create function pg_temp.directory_save(c jsonb,op uuid default gen_random_uuid())returns jsonb language sql as $$select public.save_directory('d1000000-0000-4000-8000-000000000001',op,c::text)$$;
create function pg_temp.directory_create(rev integer,n text default 'Kira Stone',op uuid default gen_random_uuid())returns jsonb language sql as $$select pg_temp.directory_save(jsonb_build_object('action','create','directory_revision',rev,'name',n,'description','Site contact','phone','internal extension 23','email','local string'),op)$$;
create temp table directory_results(k text primary key,v jsonb);grant all on directory_results to authenticated;
