-- Full retained contact population verifies complete literal search and paging without Auth accounts.
insert into public.directory_work_contacts(tenant_id,name,description,phone,email)select 'd1000000-0000-4000-8000-000000000001','Contact '||lpad(n::text,4,'0'),case when n=999 then '%_[literal]'else'worker contact'end,'',''from generate_series(1,999)n;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000980950',false);
do $$declare r jsonb;cursor text;allids uuid[]:=array[]::uuid[];nextids uuid[];begin loop r:=pg_temp.directory_read(case when cursor is null then '{"limit":100}'::jsonb else jsonb_build_object('limit',100,'cursor',cursor)end);select array_agg((v->>'id')::uuid)into nextids from jsonb_array_elements(r->'contacts')v;allids:=allids||nextids;cursor:=r->'page'->>'nextCursor';exit when cursor is null;end loop;perform pg_temp.directory_check(cardinality(allids)=1000 and(select count(distinct x)from unnest(allids)x)=1000,'all1000contacts coherent completepaging');end$$;
select pg_temp.directory_check(pg_temp.directory_read('{"q":"%_[literal]"}')->'page'->>'total'='1','literalsearch noSQLwildcard interpretation');
select pg_temp.directory_error($q$select pg_temp.directory_create(5)$q$,'54000','contact1001whole capacitydenial');
insert into directory_results values('page',pg_temp.directory_read('{"limit":1}'));
select pg_temp.directory_error($q$select pg_temp.directory_read(jsonb_build_object('cursor',E'\n'||(select v->'page'->>'nextCursor'from directory_results where k='page')))$q$,'22023','noncanonicalbase64 cursor denied');
select pg_temp.directory_error($q$select pg_temp.directory_read(jsonb_build_object('cursor',replace(encode(convert_to('{"scope":{},"scope":{},"position":1}','UTF8'),'base64'),E'\n','')))$q$,'22023','duplicated decodedcursorfields denied');
reset role;
-- Retained operations include closures. Existing receipts must precede quota checking.
insert into workforce_private.directory_operations(tenant_id,actor_id,operation_id,action,state)select 'd1000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000980950',('d6100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'create','closed_absent'from generate_series(1,20000-(select count(*)from workforce_private.directory_operations where tenant_id='d1000000-0000-4000-8000-000000000001'))n;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000980950',false);
select pg_temp.directory_check(public.reconcile_directory_operation('d1000000-0000-4000-8000-000000000001','d6000000-0000-4000-8000-000000000002','create',null)->>'status'='recorded','recordedreceipt recoverable atfull20kquota');
select pg_temp.directory_check(pg_temp.directory_create(1,'Kira Stone','d6000000-0000-4000-8000-000000000002')=(select v from directory_results where k='created'),'recorded replay atfullquotabeforestalerevision');
select pg_temp.directory_error($q$select public.reconcile_directory_operation('d1000000-0000-4000-8000-000000000001','d6000000-0000-4000-8000-000000000099','create',null)$q$,'54000','fullquota absenceclosure errors neverfalselynotrecorded');
select pg_temp.directory_error($q$select pg_temp.directory_save(jsonb_build_object('action','visibility','directory_revision',5,'contact_id',(select v->>'contact_id'from directory_results where k='created'),'contact_revision',4,'visible_in_app',false))$q$,'54000','fullquota freshvisibility denied whole');
reset role;
select pg_temp.directory_check((select count(*)from workforce_private.directory_operations where tenant_id='d1000000-0000-4000-8000-000000000001')=20000 and(select management_revision from public.directory_state where tenant_id='d1000000-0000-4000-8000-000000000001')=5,'quota failures retain exact operations/directory state');
set role anon;select pg_temp.directory_error($q$select public.read_directory_access('d1000000-0000-4000-8000-000000000001')$q$,'42501','anon cannot executeentryRPC');reset role;
set role service_role;select pg_temp.directory_error($q$select public.save_directory('d1000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"action":"activate","directory_revision":0}')$q$,'42501','service_role cannotexecute mutation');reset role;
